INSERT INTO content (key, value) VALUES ('faqs', '[{"q": "How do I book?", "a": "Send us an enquiry from any property page or the enquiry form. Our team checks availability and sends you a quote on WhatsApp. When you accept, we confirm the booking and share payment details (UPI or bank transfer)."}, {"q": "Is breakfast included?", "a": "It depends on the property and room. Each room on the property page shows what is included. Breakfast is included where the room says \"Includes: Breakfast\"."}, {"q": "What is your cancellation policy?", "a": "Free cancellation up to 7 days before check-in. 50% refund 3–7 days before. No refund within 3 days of check-in. Refunds go back to the original payment method within 5–7 working days."}, {"q": "When will I get check-in details?", "a": "One day before your check-in we send the address, map link and property contact on WhatsApp."}, {"q": "Do you arrange taxis or pickups?", "a": "Yes, we can arrange airport and railway station pickups at extra cost. Ask our team on WhatsApp or mention it in special requests."}, {"q": "Are pets allowed?", "a": "Some properties are pet-friendly — use the \"Pet-friendly\" filter in search. Please tell us about your pet before booking."}, {"q": "What ID do I need?", "a": "All adult guests need a government photo ID such as Aadhaar, passport, driving licence or voter ID at check-in."}, {"q": "What time is check-in and check-out?", "a": "Usually check-in is from 2pm and check-out is by 11am. Houseboats check in at 12 noon and check out at 9am. Each property page shows its own times."}]');
INSERT INTO content (key, value) VALUES ('about', 'Go Sanchari is a Kochi-based travel team that personally checks every homestay, villa, resort and houseboat we list across Kerala.
INSERT INTO content (key, value) VALUES ('policies', '{"cancellation": "Free cancellation up to 7 days before check-in. 50% refund 3–7 days before. No refund within 3 days of check-in.\n\nRefunds are approved by our team and sent to the original payment method within 5–7 working days. Date changes are subject to availability and any difference in rates. Houseboat bookings are non-refundable within 7 days of check-in because of weather and crew planning.", "privacy": "We collect your name, phone, email and booking details only to arrange your stay. We share the guest name and phone with the property you booked. We never sell your data. You can ask us to delete your data at any time by emailing hello@gosanchari.com.", "terms": "Bookings are confirmed by our team after you accept a quote and pay as agreed. Prices include GST as shown at checkout. Guests must follow each property''s house rules. Go Sanchari acts as a booking agent for partner properties."}');
INSERT INTO reviews (property_id, guest_name, rating, body, status, created_at) VALUES (1, 'Rahul Varma', 5, 'Wonderful stay in the middle of the tea estate. The food was amazing and the hosts were so caring. The road is a little bumpy for the last stretch.', 'approved', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-480.0 hours'));
INSERT INTO reviews (property_id, guest_name, rating, body, status, created_at) VALUES (1, 'Sneha Pillai', 4, 'Peaceful and clean. Loved the bonfire. Hot water took time in the morning.', 'approved', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-480.0 hours'));
